#!/usr/bin/env bash
# Replay the h7-carrier repair from a fresh `make draw` to the committed page, in a work
# directory, checking every sha256 and every generated op-list on the way. Exits non-zero on any
# mismatch.
#
# Fails loudly: the work directory must be new or empty (no sheet or akcli backup left by an
# earlier run can stand in for this one), every command's exit status is checked through pipes
# (pipefail), each generated file must be byte-identical to the committed one, and each
# `akcli draw` must report that it APPLIED - its dry-run also exits 0 having written nothing
# (TOOLING.md step 4).
#
# usage: bash replay.sh <new-or-empty-work-dir>
set -eu
set -o pipefail
here="$(cd "$(dirname "$0")" && pwd)"
root="$(cd "$here/../../../.." && pwd)"
akcli="$root/draughting/venv-akcli/bin/akcli"
DRAFT=106b21a13ceded56135f58f5638ac50d73c32b1e6a83511f9f7c336856a8c5b5
PAGE=dc9e93ea4ca6f42249df5faf7004965f83396db9f0c8e366474ca3e3ec5252af

fail() {
  echo "replay.sh: FAILED - $1" >&2
  exit 1
}

[ "$#" -eq 1 ] || fail "expected one argument, a new or empty work directory; got $#"
mkdir -p "$1"
work="$(cd "$1" && pwd)"
[ -z "$(ls -A "$work")" ] || fail "$work is not empty; replay into a new or empty directory so nothing from an earlier run is read"
[ -x "$akcli" ] || fail "akcli not found at $akcli"
sch="$work/h7-carrier.kicad_sch"

check() {
  got="$(shasum -a 256 "$sch" | cut -d' ' -f1)" || fail "could not hash $sch"
  [ "$got" = "$2" ] || fail "after $1 the sheet is $got, expected $2"
  echo "after $1: $got"
}

same() {
  cmp -s "$work/$1" "$here/$1" || fail "$1 generated by this replay differs from the committed $here/$1"
  echo "generated $1 matches the committed copy"
}

apply() {
  "$akcli" plan "$sch" --ops "$work/$1" | tail -1 || fail "akcli plan $1 failed"
  log="$("$akcli" draw "$sch" --ops "$work/$1" --apply)" || fail "akcli draw $1 --apply failed"
  echo "$log" | tail -1
  echo "$log" | grep -q 'status: APPLIED' || fail "akcli draw $1 did not report APPLIED - nothing was written"
}

make -C "$root/boards/h7-carrier" draw > "$work/make-draw.log" 2>&1 \
  || fail "make -C boards/h7-carrier draw failed; see $work/make-draw.log"
cp "$root/build/draw/h7-carrier/h7-carrier.kicad_sch" "$sch" || fail "make draw wrote no sheet"
cmp -s "$root/build/draw/h7-carrier.intent.json" "$here/intent.json" \
  || fail "the intent make draw generated differs from the committed intent.json - the model has changed since this repair"
echo "the intent make draw generated matches the committed intent.json"
check "make draw" "$DRAFT"

python3 "$here/net_strokes.py" "$sch" > "$work/net_strokes.json" || fail "net_strokes.py failed"
same net_strokes.json
python3 "$here/01-place.py" "$sch" > "$work/01-place.json" || fail "01-place.py failed"
same 01-place.json
apply 01-place.json
python3 "$here/pins.py" "$sch" > "$work/pins.json" || fail "pins.py failed"
same pins.json
python3 "$here/02-wire.py" "$work/pins.json" h7-carrier.kicad_sch "$work/02-wire.nets.json" \
  > "$work/02-wire.json" || fail "02-wire.py failed"
same 02-wire.json
same 02-wire.nets.json
apply 02-wire.json
python3 "$here/03-text-edits.py" "$sch" "$work/02-wire.nets.json" "$work/net_strokes.json" \
  || fail "03-text-edits.py failed"
check "01, 02 and 03" "$PAGE"
cmp -s "$sch" "$here/../h7-carrier.generated-do-not-edit.kicad_sch" \
  || fail "the replayed sheet differs from the committed page"
echo "the replayed sheet is byte-identical to the committed page"

# The committed page's sym-lib-table names the project symbol library IN PLACE in the repository
# (one copy of the symbol), where the draft's table names a copy inside the draft directory
# (tools/draught/draw-draft.ts writeProjectSymbolTable). Make the committed table here and
# require it to match byte for byte, and require the library it names to exist from the page.
lib_rel="../../../circuits/h7-platform/h7-platform.kicad_sym"
[ -f "$here/../$lib_rel" ] || fail "the committed sym-lib-table names $lib_rel, which does not exist from the page's directory"
nl="$(printf '\n')"
tab="$(printf '\t')"
printf '(sym_lib_table\n%s(version 7)\n%s(lib (name "h7-platform")(type "KiCad")(uri "${KIPRJMOD}/%s")(options "")(descr "project library, circuits/h7-platform/h7-platform.kicad_sym"))\n)\n' \
  "$tab" "$tab" "$lib_rel" > "$work/sym-lib-table" || fail "could not write the sym-lib-table"
cmp -s "$work/sym-lib-table" "$here/../sym-lib-table" \
  || fail "the sym-lib-table this replay makes differs from the committed one"
echo "the committed sym-lib-table matches the one this replay makes"
